public void processData() {
    try {
        performLowLevelIO();
    } catch (IOException e) {
        // Wrapping the low-level exception to preserve the root cause
        throw new DataProcessingException("Failed to process user input", e);
    }
}

// Custom exception implementation
public class DataProcessingException extends RuntimeException {
    public DataProcessingException(String message, Throwable cause) {
        super(message, cause);
    }
}
